    correctKey: 'C',
    explanation: 'CT二次開放は高電圧発生・絶縁破壊の危険。開放は厳禁で「精度が上がる」という記述は誤り。\n【図解】CT・VTの取扱い\n　CT二次側：開放厳禁★（高電圧発生・絶縁破壊）\n　VT二次側：短絡厳禁★（過大電流・焼損）\n　CT・VT二次側：D種接地★（一端接地）\n　（CTは電流源的・VTは電圧源的にふるまう）',
