    choices: [
      { key: 'A', text: '自家発電設備の負荷試験は、発電機の性能確認を目的とするものであり、実負荷または模擬負荷（負荷試験装置）のいずれを用いても差し支えない。', explanation: '適当。実負荷試験のほか、模擬負荷装置を用いた試験も広く行われている。' },
      { key: 'B', text: '複数台の発電機を並列運転させる場合、各発電機の周波数・電圧・位相を一致させたうえで並列にする必要がある。', explanation: '適当。同期発電機の並列運転条件は、系統に接続する変圧器の並行運転条件と同様に重要である。' },
      { key: 'C', text: '自家発電設備の負荷試験では、発電機が無負荷の状態でのみ確認を行えば十分であり、実際に負荷をかけた状態での性能確認は不要である。', explanation: '不適当。自家発電設備の負荷試験は、実際に一定の負荷をかけた状態での運転性能（電圧・周波数の安定性、燃料消費、排気温度等）を確認することが目的であり、無負荷状態の確認だけでは、実際の非常時に必要な負荷を負担できるかどうかを検証できない。「無負荷状態でのみ確認すれば十分」という記述は、負荷試験の趣旨に反しており誤りである。' },
      { key: 'D', text: '自家発電設備は、法令等で定められた負荷運転（または内部観察等）による点検を、原則として一定の頻度で実施する必要がある。', explanation: '適当。消防法令等に基づき、非常用発電設備の性能維持のための点検が求められる。' },
    ],
    correctKey: 'C',
    explanation: '負荷試験は実際に負荷をかけた状態での性能確認が目的。無負荷確認だけでは実際の非常時の性能を検証できない。\n【図解】自家発電設備の負荷試験・並列運転\n　○実負荷・模擬負荷いずれの試験方法も可★\n　○並列運転は周波数・電圧・位相の一致が必要\n　×無負荷状態の確認だけで十分（誤り）⚠\n　→ 法令等に基づき一定頻度で負荷運転点検を実施★',
