    correctKey: 'D',
    explanation: 'スマートメーターも電力量計として計量法上の検定対象であり、取引・証明用途に使用できる。「検定対象外」は誤り。\n【図解】スマートメーター・自動検針\n　○自動計測・記録し通信機能で遠隔検針が可能★\n　○30分値等の詳細な使用量データを取得可能\n　×計量法の検定対象外で取引・証明に使用不可（誤り）⚠\n　→ 現地検針の手間を省略・削減できる★',
