    correctKey: 'B',
    explanation: '積雪地域の屋外電気設備は積雪荷重を考慮した設計が必要。「標準荷重のみでよい」は地域特性を無視しており誤り。\n【図解】耐雪・耐風対策の要点\n　○強風地域は想定風圧荷重を考慮した強度設計★\n　○キュービクルには防雪カバー・ひさし等を設置\n　×積雪荷重を考慮せず標準設計でよい（誤り）⚠\n　→ 架空電線路では着氷雪荷重・ギャロッピングも考慮★',
    difficulty: 'advanced',
