    explanation: 'GR付PASは地絡事故を自動検出して開放し、波及事故を防止する。「常に手動操作のみ」はGR付PASの機能と矛盾する誤り。\n【図解】PAS・UGSの役割\n　○責任分界点付近に設置し波及事故を防止★\n　○UGS：地中引込み用の地絡保護機能付き開閉器\n　×常に手動操作のみで自動開放しない（誤り）⚠\n　→ 短絡電流の遮断は限流ヒューズ等と組み合わせて対応★',
    difficulty: 'advanced',
